double h = std::abs(b - a);
double old_int = (f(a) + f(b)) * h / 2.0;
double new_int = old_int;
int N = 2;

while (true) {
    double h_new = h / 2.0;
    new_int = 0.5 * old_int;  // reuse previous sum

    // add new midpoints
    for (int i = 0; i < N; ++i) {
        double x = a + (i + 0.5) * h;
        new_int += f(x) * h_new;
    }

    if (std::abs(new_int - old_int) < precision) {
        break;
    }

    old_int = new_int;
    h = h_new;
    N *= 2;
}

return new_int;

